select ac_cargar_unidad($ac${"slug":"alimentacion-1","rama":"alimentacion","orden":1,"nivel":1,"titulo_es":"Del campo al plato","bajada_es":"Todo lo que comés pasó por un campo, una fábrica, un camión y una góndola. Cómo funciona el sistema que te alimenta.","objetivos_es":["Describir las etapas de un sistema alimentario","Explicar por qué los alimentos de origen animal requieren más recursos","Reconocer los mensajes principales de las Guías Alimentarias argentinas","Seguir el recorrido de un alimento y la cadena de frío","Dimensionar cuánta tierra y agua usa la producción de alimentos"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":1,"fuentes":["guias-alimentarias-ar","owid-impactos-alimentos","owid-alimentos","poore-nemecek-2018","fao","inta"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"alimentacion-1.s1","orden":1,"tipo":"leccion","titulo_es":"La comida como sistema","bajada_es":"Producir, transformar, transportar, vender, comer y descartar: las etapas que hay detrás de cada bocado.","minutos":11,"pasos":[{"slug":"alimentacion-1.s1.p1","orden":1,"grupo":"alimentacion-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un sistema, no una góndola","cuerpo":["Un sistema alimentario es todo lo que hace falta para que la comida llegue a la boca: producir en el campo o el mar, transformar en industrias, transportar, almacenar, vender, cocinar, comer y descartar lo que sobra. Incluye a las personas que trabajan en cada etapa, las reglas que lo ordenan y los recursos que usa.","Mirar la comida como sistema permite ver cosas que en la góndola no aparecen: la tierra, el agua, la energía y el trabajo que hay detrás."]},"solucion":{}},{"slug":"alimentacion-1.s1.p2","orden":2,"grupo":"alimentacion-1.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del sistema alimentario de un paquete de fideos.","items":[{"id":"i1","t